package com.bank.index;

import java.util.logging.Logger;

// Validates the account-number BST using inherited min/max bounds.
public class BstValidatorService {

    private static final Logger log = Logger.getLogger(BstValidatorService.class.getName());

    public boolean isValid(AccountNode root) {
        return validate(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private boolean validate(AccountNode node, long low, long high) {
        if (node == null) {
            return true; // empty subtree is valid
        }
        long value = node.getAccountNumber();
        // Must lie strictly within the inherited open interval.
        if (value <= low || value >= high) {
            return false;
        }
        // Left subtree: upper bound tightens to current value.
        // Right subtree: lower bound tightens to current value.
        return validate(node.getLeft(), low, value)
                && validate(node.getRight(), value, high);
    }

    public boolean verifyIndex(AccountNode root) {
        boolean valid = isValid(root);
        if (valid) {
            log.info("Account index is a VALID BST — lookups safe");
        } else {
            log.severe("Account index is INVALID — misplaced record, lookups unsafe");
        }
        return valid;
    }
}
