package com.bank.index;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class ValidateBstDemo {

    private static final Logger log = Logger.getLogger(ValidateBstDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Account Index BST Validation");
        BstValidatorService service = new BstValidatorService();

        // Valid BST:        5000
        //                 /      \
        //              3000      8000
        //             /   \      /
        //          1000  4000  7000
        AccountNode valid = new AccountNode(5000);
        valid.setLeft(new AccountNode(3000));
        valid.setRight(new AccountNode(8000));
        valid.getLeft().setLeft(new AccountNode(1000));
        valid.getLeft().setRight(new AccountNode(4000));
        valid.getRight().setLeft(new AccountNode(7000));
        service.verifyIndex(valid);

        // Invalid: 6000 in the right subtree of 5000 but left of 8000
        //          violates ancestor bound (must be > 5000, ok) BUT
        // make it clearly invalid: 4500 placed as 8000's left child
        //          5000
        //         /    \
        //      3000    8000
        //              /
        //           4500   ← must be > 5000, violates ancestor bound
        AccountNode invalid = new AccountNode(5000);
        invalid.setLeft(new AccountNode(3000));
        invalid.setRight(new AccountNode(8000));
        invalid.getRight().setLeft(new AccountNode(4500)); // bad
        service.verifyIndex(invalid);
    }
}
